import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第50章 驿站","description":"","frontmatter":{},"headers":[],"relativePath":"第50章_驿站.md","filePath":"第50章_驿站.md"}'),r={name:"第50章_驿站.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第50章-驿站" tabindex="-1">第50章 驿站 <a class="header-anchor" href="#第50章-驿站" aria-label="Permalink to &quot;第50章 驿站&quot;">​</a></h1><p>高二初冬，雾散得比前些天快，风却更凉了。</p><p>放学铃响过后，教室里只剩收拾书包的动静。拉链声，书本磕桌角声，还有椅子腿蹭地的轻响。陈默拍了拍我的肩，问我去不去汤棚喝一碗热的。我摇头，说要去驿站取包裹。他挤眉弄眼，说又是书吧，你这学期收的心意可真多。我笑了一下，把围巾绕紧，推车往外走。</p><p>巷子里的风贴着脖子钻，墙角的草尖上挂着霜白。空气里有汤棚飘来的骨汤气，暖了一瞬，又被风吹散，混着远处传来的潮汐味。</p><p>驿站开在巷口拐角，门脸不大，灯却很暖。橘黄的光从玻璃门漏出来，落在青石板上，映出一小片亮。推门进去，热气扑面，混着纸箱的潮味，还有胶带淡淡的胶味。货架上堆满包裹，大的小的，层层叠叠。老板娘戴着袖套，正拿着裁刀划纸箱，刺啦一声，干脆利落。</p><p>我报了名字，她弯腰去翻。纸箱蹭着地面，发出闷闷的响。我搓了搓手，指尖被风吹得发木，这会儿被暖气一烘，微微发痒。</p><p>门帘一晃，又有人进来，带着一身凉气。</p><p>是江苒。</p><p>她穿着厚外套，围巾围到鼻尖，只露出一双眼睛。怀里抱着书包带，肩上还沾着细小的雾水。她看见我，脚步顿了一下，眼睛弯了弯，又很快压住，说，好巧，你也来扛箱子。</p><p>我说，顺路。她把围巾往下拉了拉，露出冻得发红的鼻尖，说，我才不信，顺路能顺到驿站里来，顺路费也要收的。</p><p>老板娘把两个包裹都搬了出来，一个长条形的，是我的，胶带缠得紧紧的，一个方方正正的，是她的，箱面印着书的纹理。江苒伸手去抱，试了一下，没抱动，箱子角磕在货架上，咚的一声，震得灰尘轻扬。她吐了吐舌头，说，里面是书，叶老师帮我订的，沉得很，搬得手腕都酸了。</p><p>我把自己的包裹夹在车把上，说，我帮你搬一段。她摇头，说不用，沉。我说，沉才要帮。她瞪我一眼，说，你这人，帮忙还这么凶。我说，彼此彼此，你拒绝帮忙也挺凶的。</p><p>老板娘在一旁笑，说，你们俩说话，跟点鞭炮似的，噼里啪啦。我和江苒对视一眼，都没忍住，笑了。暖气烘着脸，刚才那点凉意散了些。</p><p>出门时风又扑上来，凉意顺着袖口钻。江苒把箱子放在我的车后座，用松紧绳固定好，手指被绳勒得发红，我帮她把绳头绕两圈，打结拉紧。自己抱着我的那个长条包裹，轻轻扶着我的肩，肩头传来她掌心的暖。她说，走吧，车夫，声音贴着风。我说，得令，坐稳了，脚一点，车就往前滑去。</p><p>车轮碾过湿路面，发出细碎的沙沙声。路灯一盏一盏亮起来，光晕泡在薄雾里，软软的一团。江苒在后面晃着腿，鞋尖偶尔碰到我的脚后跟。她说，你那个长条包裹里是什么。我说，还没拆，摸着像画轴，又像裹起来的纸。她说，该不会又是纸星星吧，折都折不完。我说，星星在你那儿停了十五颗，在我这儿停了一颗，你还好意思说。</p><p>她伸手轻轻掐了一下我的肩，说，就一颗你还记仇。我说，不记仇，记挂。她在后面安静了一会儿，风声从耳边过，带着她发尾很淡的皂香。她小声说，那半颗没折完的，我夹在书里了，角总收不好，折了几次都散。</p><p>我说，我教你啊，我手法比你稳。她哼了一声，说，你稳，你上次折的那颗，肚子都是瘪的。我说，瘪的也是心意。她说，心意瘪了可不行。我说，那你教我。她说，看你表现。</p><p>车子拐过小池子，池面结了很薄的一层冰。江苒说，停车，我想看一眼。我捏了闸，脚撑地，凉气从脚踝往上爬。她抱着包裹走到池边看了看，说，去年这会儿，冰还没结呢。</p><p>起身时她忽然问，你那颗星还带在身上吗。我从口袋里摸出来，纸面被焐得发软，棱角都钝了，颜色都被手汗浸得深一点。她接过去，对着路灯看了看，纸星在光里透出暖黄，说，都摸旧了，旧得像住了人。我说，旧了也留着，旧的才踏实。她把星星还给我，指腹擦过我的掌心，凉凉的，又很快暖起来，像把风捂热了。</p><p>继续往前走，路变窄，车不好骑，我们就推着走，车轮在石板上轻轻颠。江苒抱着长条包裹，边走边用手指敲纸箱，笃笃笃，像敲鼓，声音在巷子里回荡。她说，林小满今天又把糖分错了，把海盐糖分给了顾远，顾远直皱眉，说怎么是咸的，像喝了海水。我忍不住笑，她也笑，眼睛弯成月牙，雾水落在睫毛上。</p><p>笑完她又问，陈默最近熬夜了吧，眼下都青了，像没睡醒。我说，他说题难，夜里多写了一会儿，灯亮到半夜。她叹口气，说，你们男生，怎么都喜欢硬扛，硬扛又不叫人。我说，你不也一样，耳机里放着那盘旧的课文录音带，眼圈红了也不说，盒子都捂热了。她踢了一下路边的小石子，石子滚进水洼，说，那盘带子转得慢了，调子都拖长了，听着像打瞌睡。我说，回头我帮你紧一紧，螺丝拧一拧就好。她轻轻哦了一声，耳尖有点红，被围巾遮住一半。</p><p>走到巷子中段，汤棚的香气飘过来，骨汤的热气混着姜味，肚子跟着叫了一声。江苒哈哈笑，说，车夫饿了，饿得肚子打鼓。我说，乘客也别笑，你肚子刚才也响了，像小鼓。她不承认，说那是纸箱响，是胶带在叫。我说，纸箱会叫，那成精了，要收过路费了。她赶紧扶住车把，说，慢点，书摔了叶老师要心疼的，纸角会折的。</p><p>我们把车停稳，把绳子紧了紧，指尖都勒得发白。她的手指被勒得发红，我伸手帮她揉了一下，掌心贴着她的指背，暖意传过去。她缩了一下，又没躲开，说，你手好凉，像冰块。我说，骑车吹的，风刀子似的。她把我的手合在她掌心，捂了一下，又塞回我口袋，说，揣着，暖和，别冻坏了。</p><p>那一刻风声都轻了，远处有人在喊名字，声音被雾裹着，听不真切，只有灯光在雾里晃。</p><p>她忽然从口袋里摸出一颗海盐糖，剥开，塞进我嘴里。糖纸受了潮，剥时粘手，粘在指尖。糖含在舌根，先是咸，随后化出淡甜，贴着喉咙，暖暖的，像把风含化了。她说，含一颗，推车也有力气，腿不酸。我含糊不清地说，谢乘客赏，糖化在舌尖。她笑，说，不谢，车费里扣，一颗糖换一段路。</p><p>又走了一段，宋阿婆小卖部的门开着，里面飘出热水和橘子皮的香，暖烘烘的。宋阿婆坐在柜台后头剥橘子，见我们经过，招手说，苒苒，沈聿，取包裹回来啦，冷不冷。我们应了一声，说包裹沉，先送回去，晚点再来讨杯热水。</p><p>拐过巷口，就是分路的地方，风口的风更急。江苒把长条包裹还给我，把自己的方箱子抱下来，抱得有点晃。我说，我送你到门口。她说，不用，就几步路，几步也沉。我说，几步也送，送到底才踏实。她瞪我，我也瞪她，瞪着瞪着又都笑了。她说，吵不赢还非要吵，我算服了你，服得彻底。</p><p>她抱着箱子往家的方向走了几步，又回头，把那颗海盐糖的糖纸叠小，塞进我手心，糖纸被捂得发软，说，路上别拆包裹，回家再看，听见没，听话才有糖。我说，听见了，乘客最大，最大就听你的。她挥挥手，转身走远，围巾角被风吹起来，像展翅的小鸟，很快没进雾里。</p><p>我推车回家，风吹在脸上，已经不觉得刺了，嘴里那点咸甜还没散，热毛巾的暖还留在指尖。进门放下包裹，长条纸箱上贴着一张小纸条，字很小，是很熟悉的笔迹，墨痕有点洇。我凑近看，只看清前几个字，心就跳快了，指尖在胶带上顿住。</p><p>正要撕开胶带，窗外忽然传来很轻的敲击声，一下，又一下，像指尖叩在冰面上，轻得怕惊动什么。</p>',30)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
